<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {request} from './client'
const props=defineProps({provider:Boolean})
const chosen=computed(()=>institutes.value.find(i=>i.institute===selected.value))
const institutes=ref([]),selected=ref(''),loading=ref(true),saving=ref(false),error=ref('')
async function load(){loading.value=true;error.value='';try{const data=await request('campus_context','choices',{},'GET');institutes.value=data.institutes;selected.value=data.selected||''}catch(e){error.value=e.message}finally{loading.value=false}}
async function change(){saving.value=true;error.value='';try{await request('campus_context',selected.value?'select':'clear',selected.value?{institute:selected.value}:{});window.location.assign('/campus')}catch(e){error.value=e.message;saving.value=false}}
onMounted(()=>{load();window.addEventListener('sisu-memberships',load)})
onBeforeUnmount(()=>window.removeEventListener('sisu-memberships',load))
</script>
<template><section class="campus-switcher" :class="{provider}" :aria-label="provider?'Your teaching workspaces':'Your institutes'"><div><small>{{provider?"YOUR TEACHING SPACE":"YOUR LEARNING SPACE"}}</small><h2>{{provider?"Choose your teaching workspace":"Choose your institute"}}</h2><p>{{provider?"Open your own workspace or an institute you teach with.":"Choose an institute you have joined, or return to the general campus."}}</p></div><p v-if="loading" role="status">Loading your institutes…</p><form v-else @submit.prevent="change"><label for="campus-choice">{{provider?"Teaching workspace":"Institute"}}<select id="campus-choice" v-model="selected" :disabled="saving"><option value="">{{provider?"Explore institutes — no workspace selected":"None — overall dashboard"}}</option><option v-for="item in institutes" :key="item.institute" :value="item.institute">{{item.title}} · {{item.student_number||item.role}}</option></select></label><p v-if="chosen?.student_number">Your student ID: {{chosen.student_number}}</p><button class="button primary" :disabled="saving">{{saving?'Opening…':provider?'Open workspace':'Open campus'}}</button></form><p v-if="!loading&&!error&&!institutes.length">{{provider?"Your approved teaching workspaces will appear here.":"You haven’t joined an institute yet. Your registered institutes will appear here."}}</p><div v-if="error" role="alert"><p>{{error}}</p><button class="button subtle" :disabled="saving" @click="load">Try again</button></div></section></template>
<style scoped>.campus-switcher{padding:24px;margin:16px;border:1px solid #e5ddef;border-radius:18px;background:#faf8ff;color:#38284a}.campus-switcher p{font-size:14px;line-height:1.6;margin:8px 0}.campus-switcher form{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin-top:16px}.campus-switcher label{display:grid;gap:8px;flex:1;min-width:200px}.campus-switcher select{padding:12px;border:1px solid #c6b9d5;border-radius:10px;background:white;color:#38284a;width:100%;font:inherit}.campus-switcher button{min-height:46px}@media(max-width:500px){.campus-switcher form{display:grid}.campus-switcher label{min-width:0}}</style>

<style scoped>.provider{max-width:1000px;margin:24px auto;padding:28px;background:linear-gradient(120deg,#faf8ff,#fff);box-shadow:0 8px 30px #39214d08;font-family:Manrope,system-ui,sans-serif}.campus-switcher small{font-size:10px;letter-spacing:1.4px;color:#796c8a}.campus-switcher h2{font-size:22px;margin:8px 0;letter-spacing:-.5px}.campus-switcher :is(select,button):focus-visible{outline:3px solid #b9b5fa;outline-offset:3px}@media(max-width:600px){.provider{margin:16px;padding:20px}}</style>
